function obtenerGaleriaDestino(s: SemillaDestino, _idx: number): { img: string; gallery: string[] } {
  const clave =
    s.pais === "España"
      ? "espana"
      : s.pais === "Perú"
      ? "peru"
      : s.tipo;
  const [principal, segunda, tercera, cuarta] = obtenerGaleriaPorTexto(
    `${s.slug} ${s.pais}`,
    clave
  );
  // La galería NUNCA repite la foto principal del Hero
  const galeriaSinHero = [segunda, tercera, cuarta].filter(
    (f, i, arr) => f !== principal && arr.indexOf(f) === i
  );
  return { img: principal, gallery: galeriaSinHero };
}

interface SemillaDestino {
  slug: string;
  ciudad: string;
  pais: string;
  bandera: string;
  tipo: "europa" | "caribe" | "exoticos" | "sudamerica" | "norteamerica";
  duracion: string;
  precioUSD: number;
  migratorioUSD?: number;
  tag: string;
  img: string;
  resumen: string;
  atractivo1: string;
  atractivo2: string;
  atractivo3: string;
}

